    final options = await createConversionOptionsFromJson(json: '{}');
    final result = await H2mBridge.convert(
      '<ul><li>Item 1</li><li>Item 2</li><li>Item 3</li></ul>',
      options: options,
    );
    expect(result.content, contains('- Item 1'));
    expect(result.content, contains('- Item 2'));
    expect(result.content, contains('- Item 3'));
  });

  test('A bold wrapper holding only a newline-only span still separates the words on either side', () async {
    final options = await createConversionOptionsFromJson(json: '{}');
    final result = await H2mBridge.convert(
      '<b>Alpha</b><b><span>\n</span></b><b>Beta</b>',
      options: options,
    );
    expect(
      result.content.toString(),
      equals('**Alpha** **Beta**\n'.toString()),
    );
  });

  test('A code span whose content is a single space survives', () async {
    final options = await createConversionOptionsFromJson(json: '{}');
    final result = await H2mBridge.convert(
      '<p>A<code> </code>B</p>',
      options: options,
    );
    expect(result.content.toString(), equals('A` `B\n'.toString()));
  });
}
